INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'a0f9da63-c829-55ca-88b0-c83b9b29b44f', '2a2c3c59-3904-51e5-892c-87d52adf96e7',
  '3. Cho một bàn cờ kích thước $N \times N$, trên đó chỉ có 2 loại quân cờ trắng và đen. Một nhóm định nghĩa như sau: 2 quân cờ cùng loại nằm cạnh nhau thuộc cùng 1 nhóm (nằm cạnh theo chiều ngang hoặc dọc, không tính đường chéo).
    a. [2.4] (0.5) Hiện thực cấu trúc dữ liệu cần thiết cho bàn cờ này.
    b. [8.4] (1.0) Hiện thực giải thuật tìm tất cả các quân cờ thuộc cùng nhóm bắt đầu từ 1 vị trí cho trước. Prototype của hàm như sau:
    ```cpp
    void getGroup(Board2D &b, int posX, int posY, vector<pos> &rList);
    ```
    Trong đó Board2D là kiểu dữ liệu lưu trữ bàn cờ, pos là kiểu cấu trúc chứa giá trị hàng, cột.', 3
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '0a2808e6-ce8f-5d62-be43-1257a91c27ca', '2a2c3c59-3904-51e5-892c-87d52adf96e7',
  '4. Một hệ thống hỗ trợ lái xe nhận các luồng dữ liệu camera từ các xe gọi về. Giả sử chúng ta đã có cấu trúc dữ liệu iRecord chứa dữ liệu gọi về, trong đó chứa thông tin về timestamp, vị trí chụp (longitude, latitude), vận tốc xe, và các thông số sensor khác đi kèm theo xe.
    a. [3.6] (1.0) Để phục vụ truy vấn nhanh các record, người ta thực hiện đánh chỉ mục trên timestamp, vị trí (longitude, latitude), v.v. sử dụng cây AVL. Cho cây AVL sắp xếp trên timestamp, hãy hiện thực hàm tìm kiếm các record nằm trong khoảng sai số cho trước.
    ```cpp
    bool find(AVLNode<iRecord*> *pR, int bTime, int eTime, vector<iRecord*>& &ret);
    ```
    trong đó bTime, eTime là thời gian bắt đầu và kết thúc của khoảng thời gian mà chúng ta cần truy vấn.
    b. [5.5] (1.0) Để truy vấn vị trí nhanh hơn, chúng ta sẽ tiến hành đánh chỉ mục trên vị trí bằng cách chia lưới (longitude, latitude) thành các khoảng lưới $(\Delta_{long}, \Delta_{lat})$. Với tọa độ bất kỳ $(A_{long}, A_{lat})$, ta lượng hoá về giá trị chỉ mục $(i_{long}, i_{lat})$. Từ tọa độ chỉ mục này, ta xây dựng hàm băm để truy vấn với các thông tin sau: kích thước bộ nhớ $M$, kích thước giới hạn không gian tìm kiếm $(max_{long}, max_{lat})$. Sinh viên hãy phân tích hàm đề xuất, tỉ lệ đụng độ, cách giải quyết đụng độ. Hàm có dạng sau:
    ```cpp
    void posHash(int i_{long}, int i_{lat});
    ```', 4
);

